#include <iostream>#include <string>#include <sstream>#include <vector>#include <optional>#include <variant>#include <memory>#define OUTtemplate<class... Ts>struct overloaded : Ts... {    using Ts::operator()...;};enum class TokenType {    PLUS,    MINUS,    INTEGER};struct Token {    TokenType type_;    std::variant<std::monostate,                 double> value_;    std::string toString() {        std::stringstream ss;        ss << "TokenType: ";        switch (type_) {            case TokenType::PLUS:                ss << "PLUS";            case TokenType::MINUS:                ss << "MINUS";            case TokenType::INTEGER:                ss << "INTEGER";        }        ss << "\n";        ss << "Value: ";        std::visit(overloaded {            [&ss](std::monostate) { ss << "None"; },            [&ss](double d){ ss << d;}        }, value_);        return ss.str();    }};class Tokenizer {public:    static Tokenizer& GetInstance() {        static Tokenizer tokenizer;        return tokenizer;    }    void Tokenize(const std::string& src, OUT std::vector<Token>& tokens) {        index_ = 0;        src_ = src;        ConsumeWhitespace();        while (Peek().has_value()) {            ConsumeWhitespace();            auto curr_char = Consume().value();            switch (curr_char) {                case '+': tokens.emplace_back(Token{TokenType::PLUS, std::monostate{} });                case '-': tokens.emplace_back(Token{TokenType::MINUS, std::monostate{} });                default: {                    if (std::isdigit(curr_char)) {                        std::string num {curr_char};                        while (Peek().has_value() && std::isdigit(Peek().value())) {                            num += Consume().value();                        }                        tokens.emplace_back(Token{TokenType::INTEGER, std::stod(num)});                    }                }            }        }    }private:    std::optional<char> Peek() {        if (index_ >= src_.size())            return std::nullopt;        return src_[index_];    }    std::optional<char> Consume() {        if (index_ >= src_.size())            return std::nullopt;        auto curr_char = src_[index_];        index_;        return curr_char;    }    std::string PeekN(int n) {        std::string s;        for (int i = 0; i < n; i++) {            if (!Peek().has_value())                break;            s += Consume().value();        }        return s;    }    void ConsumeWhitespace() {        while (Peek().has_value() && Peek().value() == ' ')            Consume();    }    Tokenizer() = default;    std::string src_;    std::size_t index_;};struct ASTNode {};class Parser {public:    static Parser& GetInstance() {        static Parser parser;        return parser;    }    std::shared_ptr<ASTNode> Parse(const std::vector<Token>& tokens) {    }private:    Parser() = default;    std::vector<Token> tokens_;    std::size_t index_;};class Interpreter {public:    static Interpreter& GetInstance() {        static Interpreter instance;        return instance;    }    void Interpret(std::string& src) {        Tokenizer& tokenizer = Tokenizer::GetInstance();        std::vector<Token> tokens;        tokenizer.Tokenize(src, tokens);    }private:    Interpreter() = default;};int main() {    Interpreter& interpreter = Interpreter::GetInstance();    while (true) {        std::cout << "Twig> " << std::flush;        std::string line;        std::getline(std::cin, line);        if (std::cin.eof())            exit(1);        interpreter.Interpret(line);    }    return 0;}